import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.BDCokyix.js";const h=JSON.parse('{"title":"Backend/Desktop Contract Inventory","description":"","frontmatter":{},"headers":[],"relativePath":"contracts/inventory.md","filePath":"contracts/inventory.md","lastUpdated":1780254295000}'),r={name:"contracts/inventory.md"};function n(i,t,c,s,l,p){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="backend-desktop-contract-inventory" tabindex="-1">Backend/Desktop Contract Inventory <a class="header-anchor" href="#backend-desktop-contract-inventory" aria-label="Permalink to &quot;Backend/Desktop Contract Inventory&quot;">​</a></h1><p>This document tracks the shared contract surface between the desktop runtime crates (<code>soma-daemon</code>, <code>soma-agentd</code>) and the Tauri host, which embeds them in-process via the <code>desktop-daemon</code> / <code>desktop-agent</code> crates. The host exposes the behaviour as transport-agnostic <code>desktop-api</code> handlers wrapped as <code>#[tauri::command]</code>s in <code>desktop-commands</code>; the renderer calls them through the typed <code>@soma/sdk</code> facade. The <code>proto/</code> files are Rust-only libp2p wire formats — there is no gRPC service, no Unix socket, and no napi addon. (The RPC names in the tables below are the conceptual operation names; on the wire they are Tauri commands, and the renderer types are generated from the command graph via <code>tauri-specta</code>.)</p><p><strong>Last Updated:</strong> 2026-05-16</p><h2 id="status-legend" tabindex="-1">Status Legend <a class="header-anchor" href="#status-legend" aria-label="Permalink to &quot;Status Legend&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>implemented</code></td><td>Declared in proto, implemented in backend, exposed in desktop</td></tr><tr><td><code>unimplemented</code></td><td>Declared in proto, returns <code>UNIMPLEMENTED</code> in backend</td></tr><tr><td><code>declared-only</code></td><td>Declared in proto but no backend server exists</td></tr><tr><td><code>desktop-hidden</code></td><td>Implemented in backend but not exposed via desktop wrapper</td></tr><tr><td><code>transitional</code></td><td>Implemented but semantics are unstable/ambiguous</td></tr></tbody></table><hr><h2 id="daemon-v1-daemon-in-process-surface-via-desktop-daemon-exposed-through-desktop-api-→-tauri-commands" tabindex="-1">daemon.v1.Daemon (in-process surface via <code>desktop-daemon</code>, exposed through <code>desktop-api</code> → Tauri commands) <a class="header-anchor" href="#daemon-v1-daemon-in-process-surface-via-desktop-daemon-exposed-through-desktop-api-→-tauri-commands" aria-label="Permalink to &quot;daemon.v1.Daemon (in-process surface via `desktop-daemon`, exposed through `desktop-api` → Tauri commands)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>RPC</th><th>Proto</th><th>Backend</th><th>Desktop</th><th>Docs</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td><code>Status</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>implemented</code></td><td>Returns peer_id + listen_addrs</td></tr><tr><td><code>JoinSpace</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>transitional</code></td><td>Returns submission state, not approval; emits <code>joinSubmitted</code> event</td></tr><tr><td><code>StreamEvents</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>transitional</code></td><td>Can duplicate <code>joinSubmitted</code> on reconnect; no replay semantics documented</td></tr><tr><td><code>RevokeSpace</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>implemented</code></td><td>Deletes local membership; clears local cache if self-revocation</td></tr><tr><td><code>ListSpaceMembers</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>implemented</code></td><td>Lists membership rows for a space</td></tr><tr><td><code>ListMyMemberships</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>implemented</code></td><td>Lists memberships where subject = self</td></tr><tr><td><code>IssueIssuerCapability</code></td><td>✅</td><td>✅</td><td>❌</td><td>❌</td><td><code>desktop-hidden</code></td><td>Owner-gated daemon RPC signs and persists issuer delegation locally; desktop wrapper not exposed</td></tr><tr><td><code>DiscoverSpaces</code></td><td>✅</td><td>✅</td><td>❌</td><td>❌</td><td><code>desktop-hidden</code></td><td>Returns locally known/member spaces only; rendezvous/network discovery is not implemented</td></tr><tr><td><code>ListSpaces</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>implemented</code></td><td>Paginated space list with optional query filter</td></tr><tr><td><code>CreateSpace</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>implemented</code></td><td>Creates local space, owner membership, and owner-signed genesis artifact</td></tr><tr><td><code>GetSpace</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>implemented</code></td><td>Fetch single space by ID</td></tr><tr><td><code>UpdateSpace</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>implemented</code></td><td>Update display_name</td></tr><tr><td><code>DeleteSpace</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>implemented</code></td><td>Hard delete space record</td></tr><tr><td><code>ListJoinRequests</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>transitional</code></td><td>Lists pending incoming join requests; semantics broader than name suggests</td></tr><tr><td><code>DecideJoin</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>transitional</code></td><td>Approve/reject; signs capability on approve; pushes decision via mailbox if offline</td></tr><tr><td><code>UploadBlob</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>implemented</code></td><td>Content-addressed blob storage; emits <code>YooptaBlobAdded</code> if doc_id provided</td></tr><tr><td><code>ReadBlob</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>transitional</code></td><td><code>mime</code> field hardcoded to <code>application/octet-stream</code> (ignores stored MIME)</td></tr><tr><td><code>GetBlobMetadata</code></td><td>✅</td><td>✅</td><td>❌</td><td>❌</td><td><code>desktop-hidden</code></td><td>Implemented in backend; not exposed in daemon-client.ts</td></tr><tr><td><code>ListBlobs</code></td><td>✅</td><td>✅</td><td>❌</td><td>❌</td><td><code>desktop-hidden</code></td><td>Implemented in backend; not exposed in daemon-client.ts</td></tr><tr><td><code>UpsertDocument</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>implemented</code></td><td>Stores Yoopta JSON draft</td></tr><tr><td><code>GetDocument</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>implemented</code></td><td>Fetch Yoopta JSON draft</td></tr><tr><td><code>EnsurePage</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>implemented</code></td><td>Create page record if not exists</td></tr><tr><td><code>ListPages</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>implemented</code></td><td>List page records for space</td></tr><tr><td><code>UpdatePageTitle</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>implemented</code></td><td>Update page title</td></tr><tr><td><code>SetPageParents</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>implemented</code></td><td>Set page parent hierarchy</td></tr></tbody></table><h3 id="daemon-events-streamevents" tabindex="-1">Daemon Events (StreamEvents) <a class="header-anchor" href="#daemon-events-streamevents" aria-label="Permalink to &quot;Daemon Events (StreamEvents)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Event</th><th>Proto</th><th>Backend Emits</th><th>Desktop Maps</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td><code>JoinDecisionEvent</code></td><td>✅</td><td>✅</td><td>✅</td><td><code>implemented</code></td><td>Received join decision from peer</td></tr><tr><td><code>JoinSubmitEvent</code></td><td>✅</td><td>✅</td><td>✅</td><td><code>transitional</code></td><td>Emitted on join submission; can duplicate</td></tr><tr><td><code>JoinFailedEvent</code></td><td>✅</td><td>✅</td><td>✅</td><td><code>implemented</code></td><td>Outbound join request failed</td></tr><tr><td><code>YooptaBlobAddedEvent</code></td><td>✅</td><td>✅</td><td>✅</td><td><code>implemented</code></td><td>Legacy: blob uploaded with doc_id association</td></tr><tr><td><code>DocumentBlobAddedEvent</code></td><td>✅</td><td>✅</td><td>✅</td><td><code>implemented</code></td><td>Preferred: alias for YooptaBlobAddedEvent</td></tr></tbody></table><hr><h2 id="agent-v1-agent-in-process-surface-via-desktop-agent-exposed-through-desktop-api-→-tauri-commands" tabindex="-1">agent.v1.Agent (in-process surface via <code>desktop-agent</code>, exposed through <code>desktop-api</code> → Tauri commands) <a class="header-anchor" href="#agent-v1-agent-in-process-surface-via-desktop-agent-exposed-through-desktop-api-→-tauri-commands" aria-label="Permalink to &quot;agent.v1.Agent (in-process surface via `desktop-agent`, exposed through `desktop-api` → Tauri commands)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>RPC</th><th>Proto</th><th>Backend</th><th>Desktop</th><th>Docs</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td><code>Status</code></td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td><code>implemented</code></td><td>Returns version; default models and model list are empty</td></tr><tr><td><code>ListModels</code></td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td><code>compatibility</code></td><td>Returns an empty list from agentd</td></tr><tr><td><code>InlineComplete</code></td><td>✅</td><td>✅</td><td>❌</td><td>✅</td><td><code>compatibility-stub</code></td><td>Returns <code>UNIMPLEMENTED</code> from agentd</td></tr><tr><td><code>Chat</code></td><td>✅</td><td>✅</td><td>❌</td><td>✅</td><td><code>compatibility-stub</code></td><td>Returns <code>UNIMPLEMENTED</code> from agentd</td></tr><tr><td><code>ChatStream</code></td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td><code>compatibility-stub</code></td><td>Returns <code>UNIMPLEMENTED</code> from agentd</td></tr><tr><td><code>Embed</code></td><td>✅</td><td>✅</td><td>❌</td><td>✅</td><td><code>compatibility-stub</code></td><td>Returns <code>UNIMPLEMENTED</code> from agentd</td></tr><tr><td><code>Rerank</code></td><td>✅</td><td>✅</td><td>✅</td><td>✅</td><td><code>compatibility-stub</code></td><td>Returns <code>UNIMPLEMENTED</code> from agentd</td></tr><tr><td><code>ResolveDrift</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>implemented</code></td><td>Merge Yjs updates</td></tr><tr><td><code>EnqueueBackgroundTask</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>compatibility</code></td><td>Persists a failed task record; no model worker</td></tr><tr><td><code>ListBackgroundTasks</code></td><td>✅</td><td>✅</td><td>✅</td><td>❌</td><td><code>implemented</code></td><td>Query background task status</td></tr></tbody></table><h3 id="agent-client-dual-path-behavior" tabindex="-1">Agent Client Dual-Path Behavior <a class="header-anchor" href="#agent-client-dual-path-behavior" aria-label="Permalink to &quot;Agent Client Dual-Path Behavior&quot;">​</a></h3><p>The host&#39;s <code>desktop-agent</code> crate has two runtime paths:</p><ul><li><strong>agentd library path</strong>: in-process calls into the embedded <code>soma-agentd</code> for <code>agentStatus</code>, <code>listModels</code>, and <code>resolveDrift</code> only</li><li><strong>openai-compatible path</strong>: Direct HTTP calls to OpenAI-compatible endpoints (Ollama, etc.) for chat / list-models / rerank</li></ul><p>This means not all agent features are strictly bound to <code>agent.proto</code>. See Phase 3 deliverable.</p><hr><h2 id="space-v1-membershipservice-p2p-declared-only" tabindex="-1">space.v1.MembershipService (P2P / declared only) <a class="header-anchor" href="#space-v1-membershipservice-p2p-declared-only" aria-label="Permalink to &quot;space.v1.MembershipService (P2P / declared only)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>RPC</th><th>Proto</th><th>Backend Server</th><th>Desktop</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td><code>SubmitJoinRequest</code></td><td>✅</td><td>❌</td><td>❌</td><td><code>declared-only</code></td><td>No gRPC server; daemon handles join via libp2p protocol</td></tr><tr><td><code>SubscribeJoinRequests</code></td><td>✅</td><td>❌</td><td>❌</td><td><code>declared-only</code></td><td>No gRPC server</td></tr><tr><td><code>DecideJoin</code></td><td>✅</td><td>❌</td><td>❌</td><td><code>declared-only</code></td><td>No gRPC server; daemon has <code>Daemon/DecideJoin</code> instead</td></tr><tr><td><code>SubscribeJoinDecisions</code></td><td>✅</td><td>❌</td><td>❌</td><td><code>declared-only</code></td><td>No gRPC server</td></tr><tr><td><code>GrantIssuer</code></td><td>✅</td><td>❌</td><td>❌</td><td><code>declared-only</code></td><td>No gRPC server</td></tr><tr><td><code>PublishRevocation</code></td><td>✅</td><td>❌</td><td>❌</td><td><code>declared-only</code></td><td>No gRPC server</td></tr><tr><td><code>SubscribeRevocations</code></td><td>✅</td><td>❌</td><td>❌</td><td><code>declared-only</code></td><td>No gRPC server</td></tr></tbody></table><p><strong>Resolution:</strong> <code>MembershipService</code> is a design-time artifact. The join/membership flow is implemented via:</p><ul><li><code>Daemon/JoinSpace</code> → libp2p <code>/soma/join/1</code> protocol</li><li><code>Daemon/DecideJoin</code> → libp2p <code>/soma/join-decision/1</code> protocol</li><li>Storage via <code>soma-membership</code> crate</li></ul><p>Desktop stubs are generated for message types but the service is not bound.</p><hr><h2 id="space-v1-mailboxservice-p2p-declared-only" tabindex="-1">space.v1.MailboxService (P2P / declared only) <a class="header-anchor" href="#space-v1-mailboxservice-p2p-declared-only" aria-label="Permalink to &quot;space.v1.MailboxService (P2P / declared only)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>RPC</th><th>Proto</th><th>Backend Server</th><th>Desktop</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td><code>PutItem</code></td><td>✅</td><td>❌</td><td>❌</td><td><code>declared-only</code></td><td>No gRPC server; mailbox is DB-backed in botd/daemon</td></tr><tr><td><code>Fetch</code></td><td>✅</td><td>❌</td><td>❌</td><td><code>declared-only</code></td><td>No gRPC server; used internally via libp2p</td></tr></tbody></table><p><strong>Resolution:</strong> <code>MailboxService</code> is used for message types but not exposed as a gRPC server. Mailbox operations are internal to <code>soma-membership</code> and <code>soma-peer</code>.</p><hr><h2 id="high-risk-semantic-gaps" tabindex="-1">High-Risk Semantic Gaps <a class="header-anchor" href="#high-risk-semantic-gaps" aria-label="Permalink to &quot;High-Risk Semantic Gaps&quot;">​</a></h2><p>These require documentation and/or fixes before backend/desktop can evolve independently:</p><h3 id="_1-joinspace-is-async-submission-not-approval" tabindex="-1">1. <code>JoinSpace</code> is async submission, not approval <a class="header-anchor" href="#_1-joinspace-is-async-submission-not-approval" aria-label="Permalink to &quot;1. `JoinSpace` is async submission, not approval&quot;">​</a></h3><ul><li><strong>Current:</strong> Returns <code>request_id</code> immediately; approval arrives via <code>JoinDecisionEvent</code> later</li><li><strong>Risk:</strong> UI may assume immediate success/failure</li><li><strong>Action:</strong> Document async flow; consider renaming to <code>SubmitJoinRequest</code> in future version</li></ul><h3 id="_2-reject-pending-encoding" tabindex="-1">2. <code>reject-pending</code> encoding <a class="header-anchor" href="#_2-reject-pending-encoding" aria-label="Permalink to &quot;2. `reject-pending` encoding&quot;">​</a></h3><ul><li><strong>Current:</strong> Bot may return a rejection-like placeholder when manual approval is pending</li><li><strong>Risk:</strong> Ambiguous state; cannot distinguish &quot;rejected&quot; from &quot;waiting for manual&quot;</li><li><strong>Action:</strong> Formalize pending state or stop encoding as reject</li></ul><h3 id="_3-streamevents-duplication" tabindex="-1">3. <code>StreamEvents</code> duplication <a class="header-anchor" href="#_3-streamevents-duplication" aria-label="Permalink to &quot;3. `StreamEvents` duplication&quot;">​</a></h3><ul><li><strong>Current:</strong> <code>joinSubmitted</code> can emit multiple times on reconnect</li><li><strong>Risk:</strong> UI may treat each emit as a new request</li><li><strong>Action:</strong> Document reconnect semantics; consider event IDs for dedup</li></ul><h3 id="_4-listjoinrequests-scope" tabindex="-1">4. <code>ListJoinRequests</code> scope <a class="header-anchor" href="#_4-listjoinrequests-scope" aria-label="Permalink to &quot;4. `ListJoinRequests` scope&quot;">​</a></h3><ul><li><strong>Current:</strong> Returns only pending incoming requests</li><li><strong>Risk:</strong> Name suggests broader scope; may need outgoing request tracking</li><li><strong>Action:</strong> Document current scope; add <code>ListMyJoinRequests</code> for outgoing if needed</li></ul><h3 id="_5-readblobresponse-mime-hardcoded" tabindex="-1">5. <code>ReadBlobResponse.mime</code> hardcoded <a class="header-anchor" href="#_5-readblobresponse-mime-hardcoded" aria-label="Permalink to &quot;5. `ReadBlobResponse.mime` hardcoded&quot;">​</a></h3><ul><li><strong>Current:</strong> Backend ignores stored MIME; always returns <code>application/octet-stream</code></li><li><strong>Risk:</strong> UI cannot rely on MIME for rendering decisions</li><li><strong>Action:</strong> Fix to return stored MIME or document limitation</li></ul><h3 id="_6-chatstream-ownership" tabindex="-1">6. <code>ChatStream</code> ownership <a class="header-anchor" href="#_6-chatstream-ownership" aria-label="Permalink to &quot;6. `ChatStream` ownership&quot;">​</a></h3><ul><li><strong>Current:</strong> <code>soma-agentd</code> no longer ships model RPCs; the proto method is kept in <code>agent.proto</code> for type compatibility only</li><li><strong>Risk:</strong> Desktop callers must use the OpenAI-compatible HTTP path for model chat (Ollama / remote)</li><li><strong>Action:</strong> Remove the model methods from <code>agent.proto</code> once generated-client compatibility permits</li></ul><hr><h2 id="action-items-by-priority" tabindex="-1">Action Items by Priority <a class="header-anchor" href="#action-items-by-priority" aria-label="Permalink to &quot;Action Items by Priority&quot;">​</a></h2><h3 id="p0-breakage-risk" tabindex="-1">P0 (Breakage Risk) <a class="header-anchor" href="#p0-breakage-risk" aria-label="Permalink to &quot;P0 (Breakage Risk)&quot;">​</a></h3><ol><li>Document <code>JoinSpace</code> async semantics</li><li>Document <code>StreamEvents</code> duplication behavior</li><li>Fix or document <code>ReadBlobResponse.mime</code> limitation</li></ol><h3 id="p1-misleading-api" tabindex="-1">P1 (Misleading API) <a class="header-anchor" href="#p1-misleading-api" aria-label="Permalink to &quot;P1 (Misleading API)&quot;">​</a></h3><ol><li>Expose <code>IssueIssuerCapability</code> in desktop only when product UX is ready</li><li>Extend <code>DiscoverSpaces</code> beyond local storage if rendezvous metadata becomes a product requirement</li><li>Decide: expose <code>GetBlobMetadata</code> / <code>ListBlobs</code> in desktop or mark intentional</li></ol><h3 id="p2-dead-declarations" tabindex="-1">P2 (Dead Declarations) <a class="header-anchor" href="#p2-dead-declarations" aria-label="Permalink to &quot;P2 (Dead Declarations)&quot;">​</a></h3><ol><li>Mark <code>MembershipService</code> as <code>declared-only</code> in proto comments or remove service block</li><li>Mark <code>MailboxService</code> as <code>declared-only</code> in proto comments or remove service block</li></ol><hr><h2 id="next-steps-phase-2-5" tabindex="-1">Next Steps (Phase 2-5) <a class="header-anchor" href="#next-steps-phase-2-5" aria-label="Permalink to &quot;Next Steps (Phase 2-5)&quot;">​</a></h2><ul><li><strong>Phase 2:</strong> Document and fix high-risk semantics</li><li><strong>Phase 3:</strong> Remove or quarantine agentd model compatibility stubs</li><li><strong>Phase 4:</strong> Remove/quarantine dead declarations</li><li><strong>Phase 5:</strong> Add contract tests (proto smoke, desktop wrapper tests)</li></ul>',53)])])}const u=e(r,[["render",n]]);export{h as __pageData,u as default};
